{
  "sourceUrl": "https://sallysbakingaddiction.com/chewy-chocolate-chip-cookies/print/70437/",
  "title": "Chewy Chocolate Chip Cookies",
  "ingredients": [
    {
      "name": "all-purpose flour",
      "quantity": "2 1/4",
      "unit": "cups",
      "notes": "281g; spooned & leveled"
    },
    {
      "name": "baking soda",
      "quantity": "1",
      "unit": "teaspoon",
      "notes": null
    },
    {
      "name": "cornstarch",
      "quantity": "1 1/2",
      "unit": "teaspoons",
      "notes": null
    },
    {
      "name": "salt",
      "quantity": "1/2",
      "unit": "teaspoon",
      "notes": null
    },
    {
      "name": "unsalted butter",
      "quantity": "3/4",
      "unit": "cup",
      "notes": "170g / 12 Tbsp; melted & cooled for 5 minutes"
    },
    {
      "name": "light or dark brown sugar",
      "quantity": "3/4",
      "unit": "cup",
      "notes": "150g; packed"
    },
    {
      "name": "granulated sugar",
      "quantity": "1/2",
      "unit": "cup",
      "notes": "100g"
    },
    {
      "name": "large egg + 1 egg yolk",
      "quantity": "1",
      "unit": null,
      "notes": "at room temperature"
    },
    {
      "name": "pure vanilla extract",
      "quantity": "2",
      "unit": "teaspoons",
      "notes": null
    },
    {
      "name": "semi-sweet chocolate chips or chocolate chunks",
      "quantity": "1 1/4",
      "unit": "cups",
      "notes": "225g"
    }
  ],
  "warnings": [
    "The cookie dough requires chilling prior to shaping the cookies.",
    "Chilling the cookie dough overnight is highly recommended to prevent overspreading.",
    "The chocolate chips may not stick to the dough easily because of the melted butter."
  ]
}

